def join_labels(parts, separator):
    return separator.join(parts)

print(repr(join_labels([], ',')))
print(repr(join_labels(['가', '나'], '-')))
print(repr(join_labels(['', 'A', ''], '|')))

def find_all_positions(text, pattern):
    if pattern == '':
        raise ValueError('pattern must be nonempty')
    positions = []
    start = 0
    while True:
        position = text.find(pattern, start)
        if position == -1:
            return positions
        positions.append(position)
        start = position + 1

print(find_all_positions('ababa', 'aba'))
print(find_all_positions('가가가', '가가'))
print(find_all_positions('abc', 'z'))
try:
    print(find_all_positions('abc', ''))
except ValueError:
    print('ValueError')

def join_if_fits(parts, separator, limit):
    if limit < 0:
        raise ValueError('limit must be nonnegative')
    length = sum(len(part) for part in parts)
    length += max(len(parts) - 1, 0) * len(separator)
    if length > limit:
        return None
    return separator.join(parts)

print(repr(join_if_fits(['가', '나'], '-', 3)))
print(join_if_fits(['가', '나'], '-', 2))
print(repr(join_if_fits([], ',', 0)))
print(join_if_fits(['', ''], '|', 0))
